  "Aşamaları sonradan ekleyebilir, silebilir ve sıralayabilirsiniz. Üniversite kılavuzu yüklerseniz yeni bir düzen önerilir.": "You can add, delete and reorder stages later. If you upload a university guideline, a new structure will be suggested.",
  "Çalışma türü": "Work type",
  "Araştırma bilgileri": "Research details",
  "Gerçek kaynaklarla çalışan akademik asistan": "An academic assistant that works with real sources",
  "Akademik çalışmanızı": "Manage your academic work",
  "ilk fikirden": "from the first idea",
  "son kaynakçaya kadar yönetin.": "to the final reference list.",
  "Tez, makale ve araştırma önerinizi adım adım ilerleyen bir yol haritasıyla hazırlayın. Kaynaklar OpenAlex, Crossref ve PubMed gibi veri tabanlarından gelir ve doğrulanır. Atıflar seçtiğiniz stile göre kendiliğinden biçimlenir.": "Prepare your thesis, article and research proposal with a step-by-step roadmap. Sources come from databases such as OpenAlex, Crossref and PubMed and are verified. Citations are formatted automatically in the style you choose.",
  "Çalışmaya başla": "Start working",
  "Çalışma türlerini gör": "See work types",
  "Uydurma kaynak yok": "No fabricated sources",
  "10 atıf stili": "10 citation styles",
