  "Kavramsal çerçeve": "Conceptual framework",
  "Ebeveyn tutumları, bireyin yakın ilişkilerdeki bağlanma örüntülerini şekillendiren temel etkenler arasında yer almaktadır": "Parental attitudes are among the key factors shaping an individual’s attachment patterns in close relationships",
  "İlişki odaklı obsesif belirtiler ise partnere yönelik yineleyici şüphelerle karakterizedir": "Relationship-focused obsessive symptoms are characterised by recurrent doubts about the partner",
