  "yönlendirilen": "a guided",
  "bir akademik süreç": "academic process",
  "Altı adımda, kontrol hep sizde.": "Six steps, always under your control.",
  "Erişebildiği kadarını kullanır, ne kadarını okuduğunu söyler.": "It uses what it can access and tells you how much it read.",
  "Her kaynağın yanında erişim seviyesi açıkça yazar:": "Each source clearly shows its access level:",
  "yalnızca künye": "citation only",
  "özet okundu": "abstract read",
  "veya": "or",
  "tam metin okundu": "full text read",
  "Yapay zekâ, yalnızca özetini gördüğü bir makaleyi tam metnini okumuş gibi yorumlamaz. Doğrulanamayan kaynaklar ise kesin referans olarak gösterilmez.": "The AI does not interpret an article whose abstract is all it has seen as if it had read the full text. Sources that cannot be verified are not presented as definitive references.",
  "Akademik dürüstlük, tasarımın merkezinde.": "Academic integrity at the heart of the design.",
  "En çok tercih edilen": "Most popular",
  "/ay": "/mo",
  "{name} paketini seç": "Choose {name}",
  "Akademik süreç yönetimi": "Academic process management",
  "Çalışma türünüze, seviyenize ve yönteminize göre oluşan yol haritası. Her aşamanın kendine özel bir asistanı ve kuralları var. Bölümler arasında geçerken proje hafızası korunur.": "A roadmap based on your work type, level and method. Every stage has its own assistant and rules. The project memory is preserved as you move between sections.",
  "Dinamik aşama yapısı": "Dynamic stage structure",
  "Üniversite kılavuzundan bölüm önerisi": "Section suggestions from your university guideline",
  "İlerleme takibi": "Progress tracking",
  "Gerçek bilimsel araştırma": "Real scientific research",
  "OpenAlex, Crossref, PubMed, arXiv, DOAJ, ERIC ve diğer veri tabanlarında eşzamanlı tarama. DOI, PMID ve arXiv kimlikleri doğrulanır.": "Simultaneous search across OpenAlex, Crossref, PubMed, arXiv, DOAJ, ERIC and other databases. DOI, PMID and arXiv identifiers are verified.",
  "Erişim seviyesi şeffaflığı": "Access level transparency",
  "Açık erişimli tam metin analizi": "Open-access full-text analysis",
  "Yinelenen kayıt birleştirme": "Duplicate record merging",
  "Akademik yazım otomasyonu": "Academic writing automation",
  "Atıflar metne yazı olarak değil, kaynağa bağlı canlı öğeler olarak eklenir. Stili değiştirdiğinizde bütün metin ve kaynakça yeni stile dönüşür.": "Citations are inserted not as plain text but as live elements linked to the source. When you change the style, the entire text and reference list switch to the new style.",
  "Eksik künye ve tutarlılık uyarısı": "Incomplete citation and consistency warnings",
  "DOCX ve PDF çıktı": "DOCX and PDF output",
  "Çalışma türünü seçin": "Choose a work type",
  "Tez, makale, derleme veya araştırma önerisi seçin. Platform akademik standartlara uygun bir yol haritası çıkarır.": "Choose a thesis, article, review or research proposal. The platform builds a roadmap that meets academic standards.",
  "Konunuzu tanımlayın": "Define your topic",
  "Asistan konunuzu analiz eder, kavramları ayrıştırır ve sizinle birlikte bir çalışma planı yapar.": "The assistant analyses your topic, breaks down the concepts and creates a work plan with you.",
  "Literatürü tarayın": "Search the literature",
  "Gerçek veri tabanlarında arama yapılır. Hangi kaynakları kütüphanenize ekleyeceğinize siz karar verirsiniz.": "Real databases are searched. You decide which sources to add to your library.",
  "Bölümleri geliştirin": "Develop the sections",
  "Her bölümde yazın, yeniden yazdırın, genişletin. Her iddia bir kaynağa bağlanır, her sürüm geçmişte saklanır.": "Write, rewrite and expand each section. Every claim is linked to a source and every version is kept in the history.",
  "Atıf tutarlılığı, eksik künye, bölümler arası uyum ve akademik dil kontrol edilir.": "Citation consistency, incomplete citations, coherence across sections and academic language are checked.",
  "Dışa aktarın": "Export",
  "Word, PDF, Markdown veya TXT olarak indirin. İçindekiler, numaralandırma ve kaynakça hazır gelir.": "Download as Word, PDF, Markdown or TXT. Table of contents, numbering and reference list come ready.",
  "Künye": "Citation",
  "Özet": "Abstract",
  "Kaynak, veri, istatistik ve bulgu üretilmez. Kaynakla desteklenemeyen kesin iddia yazılmaz; eksik konular için kaynak aranır.": "No sources, data, statistics or findings are fabricated. Definitive claims that cannot be supported by a source are not written; sources are searched for missing topics.",
  "Bulgular bölümü sizin analizinize dayanır. Yüklediğiniz veriler gerçek hesaplamayla özetlenir.": "The findings section is based on your own analysis. The data you upload are summarised with real computations.",
  "Çalışmalarınız yalnızca size görünür. Satır düzeyinde güvenlik, şifreli depolama ve tek tıkla veri silme.": "Your work is visible only to you. Row-level security, encrypted storage and one-click data deletion.",
  "İntihal şeffaflığı": "Plagiarism transparency",
  "Lisanslı bir servis bağlanmadan intihal yüzdesi gösterilmez. Sahte oranlar üretilmez.": "No plagiarism percentage is shown without a licensed service connected. No fake scores are produced.",
