  "Asistan bölümün tamamına göre öneri verecek.": "The assistant will make suggestions based on the whole section.",
  "Asistanla uygula": "Apply with assistant",
  "Atla": "Skip",
  "Atlandı": "Skipped",
  "Atıf doğrulama": "Citation check",
  "Aşağıdaki paragraftaki [KAYNAK GEREKLİ] işaretli iddialar için kaynak bul ve paragrafı düzelt. ⟦C1⟧ gibi işaretler mevcut atıflardır; yerlerini ve yazımını aynen koru.": "Find sources for the claims marked [KAYNAK GEREKLİ] in the paragraph below and fix the paragraph. Markers such as ⟦C1⟧ are existing citations; keep their position and spelling exactly.",
  "Bağlantı koptuğunda bu cihazda saklanan metin sunucuya kaydedildi.": "Text stored on this device while you were offline has been saved to the server.",
  "Başlayalım": "Let’s start",
  "Belgeye tablo olarak ekle": "Insert into document as a table",
  "Biçim ayarları kaydedildi": "Format settings saved",
  "Biçim ve kapak ayarları": "Format and cover settings",
  "Bu ay {item} limitinizin %{pct} kadarını kullandınız": "You have used {pct}% of your {item} limit this month",
  "Bu bölüm için akademik standartlara uygun 3–6 alt başlık öner. Mevcut alt başlıkları tekrar etme. Yalnızca bir :::taslak bloğu içinde her satıra bir alt başlık yaz; numara veya açıklama ekleme.": "Suggest 3–6 subheadings for this section that meet academic standards. Do not repeat existing subheadings. Write only one subheading per line inside a single :::taslak block; no numbers or explanations.",
  "Bu bölümün yalnızca “{h}” alt başlığını yaz. Taslağı “## {h}” başlığıyla başlat; diğer alt başlıkları yazma. Bu alt konu için mevcut kaynaklar yetersizse yeni kaynak ara; tam metni okunan kaynaklardan aktarımlarda sayfa numarası ver. Önceki alt başlıklarda yazılanları tekrar etme, konuya yeniden giriş yapma ve alt başlığı özet cümlesiyle bitirme; yalnızca bu alt başlığa özgü yeni bilgiyi yaz.": "Write only the “{h}” subsection of this section. Start the draft with the heading “## {h}”; do not write other subsections. If existing sources are insufficient for this subtopic, search for new ones; give page numbers when drawing on sources whose full text was read. Do not repeat what earlier subheadings covered, do not re-introduce the topic, and do not end with a summary sentence; write only what is new and specific to this subheading.",
  "Bu hafta": "This week",
  "Bu hafta {w} / {g} kelime": "This week {w} / {g} words",
  "Bölüm başlıkları BÜYÜK HARF": "Chapter titles in CAPITALS",
  "Bölüm başlıkları ortalı": "Centred chapter titles",
  "Chrome, Edge veya Safari’nin güncel sürümünü deneyin.": "Try a recent version of Chrome, Edge or Safari.",
  "Cihazda saklanan taslak geri yüklendi": "Draft stored on device restored",
  "Danışman yorumu: “{c}”. Bu bölümün mevcut metnini bu yoruma göre nasıl düzeltmem gerektiğini açıkla; gerekiyorsa düzeltilmiş paragrafları taslak olarak ver.": "Advisor comment: “{c}”. Explain how I should revise the current text of this section according to this comment; if needed, give the revised paragraphs as a draft.",
  "Danışman yorumu: “{c}”. Seçili metni bu yoruma göre düzelt; düzeltilmiş metni tek bir taslak olarak ver, mevcut atıfları koru. Yaptığın değişiklikleri kısaca açıkla.": "Advisor comment: “{c}”. Revise the selected text according to this comment; give the revised text as a single draft and keep the existing citations. Briefly explain your changes.",
  "Değerlendirme yapay zekâ tarafından yalnızca okunan kaynak metnine dayanarak yapılır; son karar sizindir.": "The assessment is made by AI based only on the source text that was read; the final decision is yours.",
