  "Hedefe ulaşmak için haftada yaklaşık {n} kelime gerekiyor.": "About {n} words per week are needed to reach the goal.",
  "Hedeflenen toplam kelime (isteğe bağlı)": "Target total words (optional)",
  "Hepsini uygula ({n})": "Apply all ({n})",
  "Her alt başlık bir yapay zekâ isteği sayılır; kaynak taramaları ayrıca sayılır. En fazla 12 alt başlık.": "Each subheading counts as one AI request; source searches are counted separately. Up to 12 subheadings.",
  "Her alt başlık bitince belgeye ekle": "Add to document as each subheading finishes",
  "Her bölüm yeni sayfada başlasın": "Start each chapter on a new page",
  "Her kaynağın amacı, yöntemi, örneklemi ve bulguları yalnızca okunan özet veya tam metinden çıkarılır; metinde olmayan bilgi boş bırakılır. Yalnızca künyesi bilinen kaynaklar için içerik yazılmaz.": "Each source’s aim, method, sample and findings are extracted only from the abstract or full text that was read; information not in the text is left blank. Nothing is written for sources with citation data only.",
  "Her satıra bir alt başlık yazın. Asistan her alt başlık için ayrı ayrı kaynak tarar, açık erişimli tam metinleri okur ve o alt başlığı yazar. Bitince hangi alt başlıklarda kaynak bulunamadığını gösterir.": "Write one subheading per line. For each subheading the assistant searches for sources separately, reads open-access full texts and writes that subsection. At the end it shows which subheadings lacked sources.",
