  "{n} kaynağın tam metni okunamadı (kapalı erişim). PDF’iniz varsa yükleyin; sayfa numaralı atıf ve doğrulama mümkün olur.": "The full text of {n} sources could not be read (closed access). If you have the PDF, upload it to enable page-numbered citations and verification.",
