  "İki yana yasla": "Justify",
  "İleri": "Next",
  "İlerleme": "Progress",
  "Şablonu seçin, sonra üniversitenizin yazım kılavuzuna göre değerleri düzenleyin. Kılavuzu Proje ayarları’ndan yüklerseniz asistan da değerleri önerir.": "Choose a template, then adjust the values to your university’s writing guidelines. If you upload the guideline in Project settings, the assistant will also suggest values.",
  "Şehir": "City",
  "Şu an toplam {n} kelime; bu hafta {w} kelime yazıldı.": "{n} words in total; {w} words written this week.",
