  "Türk üniversiteleri — genel tez yazım kılavuzu": "Turkish universities — general thesis guidelines",
  "APA 7 — öğrenci ödevi / tez": "APA 7 — student paper / thesis",
  "Dergi makalesi taslağı": "Journal article draft",
  "Hedef ve takvim": "Goal and schedule",
  "Dışa aktarma ve ayarlar": "Export and settings",
  "Çalışmanızın yol haritası. Bölümler arasında buradan geçersiniz; sürükleyerek sıralayabilir, yenisini ekleyebilirsiniz.": "Your work’s roadmap. Move between sections here; drag to reorder or add new ones.",
  "Bölümü burada yazarsınız. Atıflar kaynağa bağlı canlı öğelerdir: üstüne tıklayınca sayfa ekleyebilir ve “Kaynakta doğrula” ile kaynağın gerçekten bunu söyleyip söylemediğini kontrol edebilirsiniz.": "You write the section here. Citations are live elements linked to the source: click one to add a page and use “Check in source” to see whether the source really says this.",
  "Asistan gerektiğinde kaynakları kendisi arar, okur ve sayfa numarasıyla atıf yapar. “Alt başlıklarla yaz” ile bölümün tamamını alt başlık alt başlık yazdırabilir, mikrofonla sesli not verebilirsiniz.": "The assistant searches for and reads sources when needed and cites them with page numbers. Use “Write by subheadings” to write a whole section subheading by subheading, or dictate notes with the microphone.",
  "Projedeki kaynaklar, erişim seviyeleri ve literatür matrisi burada. Tam metni okunamayan kaynaklar için PDF yükleyebilirsiniz.": "Project sources, access levels and the literature matrix are here. You can upload PDFs for sources whose full text could not be read.",
  "Kaynakça seçtiğiniz stile göre kendiliğinden oluşur. Bir kayda tıklayınca kullanıldığı yerleri görür, “Git” ile metindeki atfa gidersiniz.": "The reference list builds itself in your chosen style. Click an entry to see where it is used and “Go” to jump to the citation.",
  "Haftalık kelime hedefi ve teslim tarihi belirleyin; kalan bölümler haftalara dağıtılır.": "Set a weekly word goal and a deadline; the remaining sections are spread over the weeks.",
  "Word/PDF çıktısı, üniversite biçim şablonu ve kapak bilgileri burada. Mobilde “⋯” menüsünde atıf stili, paylaşım ve dil seçimi de var.": "Word/PDF output, university format template and cover details are here. On mobile, the “⋯” menu also has citation style, sharing and language.",
  "Bu özellik için veritabanı güncellemesi gerekiyor (20261103000006_source_summary.sql).": "This feature requires a database update (20261103000006_source_summary.sql).",
  "Dosya ve kaynak aynı projede olmalıdır": "The file and the source must be in the same project",
