  "Üniversite BAP projesi": "University research fund (BAP) project",
  "Burs başvurusu için araştırma önerisi (ör. 2211, 2214)": "Research proposal for a scholarship application (e.g. 2211, 2214)",
  "Diğer kurum / fon": "Other institution / fund",
  "Hakem yorumlarına cevap": "Response to reviewers",
  "Hakem yorumlarına cevap mektubu hazırla": "Prepare a response letter to the reviewer comments",
  "Cevap mektubu hazırla": "Prepare response letter",
  "Dergiden gelen editör kararını ve hakem yorumlarını olduğu gibi yapıştırın. Asistan çalışmanızın mevcut hâlini okuyarak her yoruma madde madde cevap veren bir mektup hazırlar ve metinde yapmanız gereken değişiklikleri sıralar.": "Paste the editor’s decision and reviewer comments as they are. The assistant reads the current version of your work, drafts a letter answering each comment point by point and lists the changes you need to make in the text.",
  "Reviewer 1:\n1. The sample size is small…\n2. …\n\nReviewer 2:\n…": "Reviewer 1:\n1. The sample size is small…\n2. …\n\nReviewer 2:\n…",
  "Henüz yapmadığınız değişiklikler mektupta [YAPILACAK: …] olarak işaretlenir; sayfa numaraları sizin doldurmanız için boş bırakılır.": "Changes you have not yet made are marked [TO DO: …] in the letter; page numbers are left blank for you to fill in.",
  "Savunma provası": "Defence rehearsal",
  "Destekleyici": "Supportive",
  "Standart jüri": "Standard committee",
  "Zorlayıcı": "Challenging",
  "Yapay zekâ jüri, çalışmanızın metnini okuyup savunmada sorulabilecek soruları hazırlar. Her soruya yazarak veya konuşarak cevap verin; cevabınızın güçlü ve eksik yönlerini ve daha iyi bir cevabın iskeletini görün.": "The AI committee reads your work and prepares questions you may be asked in your defence. Answer each by typing or speaking; see the strengths and gaps of your answer and an outline of a stronger one.",
  "Jüri tutumu": "Committee style",
  "Soru sayısı": "Number of questions",
  "Odaklanılacak konu (isteğe bağlı)": "Focus area (optional)",
  "ör. örneklem büyüklüğü, ölçeğin geçerliği": "e.g. sample size, validity of the scale",
  "Provayı başlat": "Start rehearsal",
  "Sorular yalnızca çalışmanızda yazılı olanlara dayanır. Konuşarak cevap verirken ses tarayıcınızda yazıya çevrilir, ses kaydı sunucuya gönderilmez.": "Questions are based only on what is written in your work. When you answer by speaking, your voice is transcribed in your browser; no audio is sent to the server.",
