  "Bu projeye yüklenmiş veri dosyası (CSV/XLSX) yok. “Dosyalarım” sayfasından verinizi projeye bağlayarak yükleyin veya anket cevaplarınızı projeye aktarın; ilk satır değişken adları olmalıdır.": "No data file (CSV/XLSX) is uploaded to this project. Upload your data linked to the project from “My files” or send your survey responses to the project; the first row must contain variable names.",
  "Şekil başlığı": "Figure title",
  "Not.": "Note.",
  "Grafik, verinizden gerçek hesaplamayla ve APA 7 şekil kurallarına uygun (siyah-beyaz, eksen başlıklı, numaralı) çizilir. Word ve PDF çıktısına görsel olarak eklenir.": "The chart is drawn from your data with real calculations and follows APA 7 figure rules (black and white, axis titles, numbered). It is embedded as an image in Word and PDF exports.",
