  "Önizle": "Preview",
  "Sorular": "Questions",
  "Cevaplar": "Responses",
  "Bu anket cevap almaya başladı. Veri sütunları bozulmasın diye soru ekleyip çıkaramaz, seçenek sayısını değiştiremezsiniz; yalnızca yazım düzeltmesi yapabilirsiniz. Yeni sorular için anketin kopyasını oluşturun.": "This survey has started receiving responses. To keep the data columns intact you cannot add or remove questions or change the number of options; you can only fix typos. Make a copy of the survey for new questions.",
  "Kopya oluştur": "Make a copy",
  "Aşağıdaki düğmelerle soru ekleyin. Hazır bir ölçek kullanacaksanız maddelerini “Likert ölçeği” ile tek seferde yapıştırabilirsiniz.": "Add questions with the buttons below. If you use an existing scale, paste all its items at once with “Likert scale”.",
  "Demografik sorular ekle": "Add demographic questions",
  "Başkasına ait bir ölçeği kullanıyorsanız (ör. uyarlanmış ölçekler), çoğu zaman ölçek sahibinden yazılı kullanım izni almanız gerekir. Anketi uygulamadan önce kurumunuzun etik kurul onayını almayı unutmayın.": "If you use someone else’s scale (e.g. adapted scales), you usually need written permission from its owner. Remember to obtain ethics approval from your institution before running the survey.",
