  "Merhaba, Academiana Akademik Ekip İndirimi (%{p}) hakkında bilgi almak istiyorum.\nKurum / bölüm / ekip adı: \nKişi sayısı: \nİlgilendiğimiz paket: \nÜye no: {no}\nHesap e-postam: {email}": "Hello, I would like information about the Academiana Academic Team Discount ({p}%).\nInstitution / department / team: \nNumber of people: \nPlan we are interested in: \nMember no: {no}\nAccount e-mail: {email}",
  "Merhaba, Academiana kurum lisansı / Akademik Ekip İndirimi için teklif almak istiyorum.\nKurum / bölüm / ekip adı: \nKişi sayısı: \nİlgilendiğimiz paket: ": "Hello, I would like a quote for an Academiana institutional licence / Academic Team Discount.\nInstitution / department / team: \nNumber of people: \nPlan we are interested in: ",
