  "Arkadaşını davet et, kazan": "Invite a friend, earn",
  "Davet ettiğin her arkadaş kaydolduğunda sana bir Ücretsiz paket kadar hak tanımlanır: {p} sayfa, {a} yapay zekâ isteği ve {s} kaynak tarama ({d} gün geçerli).": "For every friend you invite who signs up, you get one Free plan’s worth of allowance: {p} pages, {a} AI requests and {s} source searches (valid for {d} days).",
  "Arkadaşını davet et, ek hak kazan!": "Invite a friend, earn extra usage!",
  "Arkadaşınız bu bağlantıyla kaydolduğunda size bir Ücretsiz paket kadar hak tanımlanır: {p} sayfa, {a} yapay zekâ isteği ve {s} kaynak tarama ({d} gün geçerli).": "When your friend signs up with this link, you get one Free plan’s worth of allowance: {p} pages, {a} AI requests and {s} source searches (valid for {d} days).",
  "Davet ettiğiniz her arkadaşınız kaydolduğunda size bir Ücretsiz paket kadar hak tanımlanır: {p} sayfa, {a} yapay zekâ isteği ve {s} kaynak tarama ({d} gün geçerli).": "For every friend you invite who signs up, you get one Free plan’s worth of allowance: {p} pages, {a} AI requests and {s} source searches (valid for {d} days).",
