  "Ayda yaklaşık 50 sayfa yapay zekâ destekli akademik metin (ör. 2 makale; yüksek lisans tezi 1–2 ayda)": "About 50 pages of AI-assisted academic text per month (e.g. 2 articles; a master’s thesis in 1–2 months)",
