  "“Sayfa”: Türk tez biçiminde (Times New Roman 12 punto, 1,5 satır aralığı) yapay zekâ desteğiyle yazılan ana metin sayfası; kapak, içindekiler, kaynakça ve ekler sayılmaz. Değerler yaklaşıktır: taslakları sık yeniden yazdırmak daha az, verimli kullanım daha fazla sayfa sağlar.": "“Page”: a main-text page written with AI assistance in Turkish thesis format (Times New Roman 12 pt, 1.5 line spacing); cover, table of contents, references and appendices are not counted. Values are approximate: frequent regeneration of drafts gives fewer pages, efficient use gives more.",
  "3 proje": "3 projects",
