  "APA 7, ISNAD, MLA, IEEE dahil 10 atıf stili; kaynakça kendiliğinden oluşur": "10 citation styles including APA 7, ISNAD, MLA and IEEE; the bibliography builds itself",
  "Atıf biçimi tutarsız olabilir; kaynakçayı elle düzenlersiniz": "Citation formatting can be inconsistent; you fix the bibliography by hand",
  "OpenAlex, PubMed ve arXiv’den DergiPark’a 16 akademik veri tabanında, 250 milyondan fazla yayında doğrudan arar": "Searches more than 250 million publications in 16 academic databases directly — from OpenAlex, PubMed and arXiv to DergiPark",
  "Akademik veri tabanlarına doğrudan bağlı değildir; kaynak bulma genel web aramasına dayanır": "Not directly connected to academic databases; finding sources relies on general web search",
