  "DOI ve künyeler Crossref, PubMed ve arXiv’de tek tek kontrol edilir.": "DOIs and references are checked one by one against Crossref, PubMed and arXiv.",
  "Eksik kaynak uyarısı": "Missing-source alerts",
  "Kaynağı olmayan iddia kesin bilgi gibi yazılmaz, işaretlenir.": "A claim without a source is never stated as fact — it is flagged.",
  "Doğrulanabilir atıflar": "Verifiable citations",
  "Her iddianın izi sürülebilir": "Every claim is traceable",
  "Paragraftaki her atıf gerçek bir kaynağa bağlanır: atıfa dokun, kaynağı ve doğrulamasını gör. Kaynağı olmayan iddia sessizce yazılmaz; işaretlenir.": "Every citation in a paragraph links to a real source: tap it to see the source and how it was verified. A claim without a source isn’t quietly written — it’s flagged.",
