  "Örnek gösterimdir; kaynaklar ve pasajlar temsilidir. Kendi çalışmanızda pasajlar, eklediğiniz kaynakların kendi metninden gelir. Bir atıfın veya kaynağın üzerine gelerek doğrulamayı görün.": "Sample illustration; the sources and passages are representative. In your own work, passages come from the actual text of the sources you add. Hover over a citation or source to see the verification.",
  // Silme düğmeleri (D65)
  "“{title}” çalışması; tüm bölümleri, kaynakları, sohbetleri ve sürümleriyle birlikte kalıcı olarak silinsin mi? Bu işlem geri alınamaz.": "Permanently delete “{title}” together with all its sections, sources, chats and versions? This cannot be undone.",
