  "“{title}” kaynağı kalıcı olarak silinsin mi? Metinde bu kaynağa verilen atıflar kaynaksız kalır.": "Permanently delete the source “{title}”? Citations to it in your text will be left without a source.",
  "Silinemedi": "Could not delete",
  "“{title}” anketi ve tüm cevapları kalıcı olarak silinsin mi? Bu işlem geri alınamaz.": "Permanently delete the survey “{title}” and all its responses? This cannot be undone.",
  "Bu kayıt kalıcı olarak silinsin mi? Bu işlem geri alınamaz.": "Permanently delete this item? This cannot be undone.",
  "Silindi": "Deleted",
