  "Bu bölümdeki asistan sohbeti ve tüm mesajları kalıcı olarak silinsin mi? Metninize eklediğiniz yazılar etkilenmez.": "Permanently delete the assistant chat for this section and all its messages? Text you added to your document is not affected.",
  "Bu hafıza kaydı kalıcı olarak silinsin mi?": "Permanently delete this memory item?",
