  "İnceleme:": "Review:",
  "Aşağıdaki düğmelerle soru ekleyin. Hazır bir ölçek kullanacaksanız maddelerini “Likert ölçeği” ile tek seferde yapıştırabilirsiniz. İpucu: Likert ölçeği ekleyip yalnızca ölçmek istediğiniz kavramı yazın, ✨ düğmesiyle maddeleri yapay zekâ önersin.": "Add questions with the buttons below. To use an existing scale, paste its items in one go with “Likert scale”. Tip: add a Likert scale, write only the concept you want to measure, and let AI suggest items with the ✨ button.",
  "Likert ölçeğinde yönergeyi veya ölçmek istediğiniz kavramı yazmanız yeterli; maddeleri yapay zekâ önerir.": "For a Likert scale, just write the instruction or the concept you want to measure; AI suggests the items.",
  "Madde öner": "Suggest items",
