  "Dili sadeleştir, lise öğrencileri anlayabilsin": "Simplify the language for high school students",
  "Sona 2 açık uçlu soru ekle": "Add 2 open-ended questions at the end",
  "Demografik sorulara eğitim düzeyi ve gelir ekle": "Add education level and income to demographics",
  "Tüm anketi İngilizceye çevir": "Translate the whole survey into English",
