  "Bilgilendirilmiş onam metni yok. Etik kurullar çoğunlukla ister (Ayarlar sekmesi).": "There is no informed consent text. Ethics committees usually require one (Settings tab).",
  "Onam metninde doldurulmamış alanlar var (köşeli parantez içindekiler).": "The consent text has unfilled fields (those in square brackets).",
  "Demografik soru yok. Örneklemi betimlemek için yaş, cinsiyet gibi sorular eklemeyi düşünün.": "There are no demographic questions. Consider adding age, gender etc. to describe the sample.",
  "Anket yaklaşık {n} dakika sürüyor. 15–20 dakikayı aşan anketlerde yarıda bırakma artar.": "The survey takes about {n} minutes. Drop-out rises for surveys longer than 15–20 minutes.",
  "{n}. soruda, {m}. sorudaki bir ifadenin aynısı var.": "Question {n} repeats a statement from question {m}.",
  "{n}. sorudaki “{x}” maddesi iki şeyi birden soruyor olabilir; gerekirse iki maddeye ayırın.": "Item “{x}” in question {n} may ask two things at once; split it if needed.",
  "{n}. sorudaki ölçekte ters madde yok. Hep aynı yönde cevaplamayı fark etmek için 1–2 ters madde eklenebilir.": "The scale in question {n} has no reverse-scored items. Adding 1–2 helps detect straight-lining.",
  "{n}. sorudaki ölçek {k} maddeden oluşuyor; katılımcı yorulabilir, bölmeyi düşünün.": "The scale in question {n} has {k} items; participants may tire, consider splitting it.",
  "{n}. soru (sayı) için alt/üst sınır yok; hatalı girişleri önlemek için aralık belirleyin.": "Question {n} (number) has no min/max; set a range to prevent invalid entries.",
  "{n}. soruda (çoklu seçim) “Diğer” seçeneği yok.": "Question {n} (multiple choice) has no “Other” option.",
  "{n}. soruda {k} seçenek var; uzun listeler okunmayabilir.": "Question {n} has {k} options; long lists may not be read.",
