  "Kaydedilmemiş değişiklikler var. Kaydetmeden kapatılsın mı?": "There are unsaved changes. Close without saving?",
  "Kendim yazacağım": "I’ll write it myself",
  "Kurgu bir plandır: kaynak, bulgu veya istatistik içermez. Önerilen örneklem ve analizleri danışmanınızla birlikte kesinleştirin.": "The blueprint is a plan: it contains no sources, findings or statistics. Finalise the suggested sample and analyses with your advisor.",
  "Kurgu kaydedildi": "Blueprint saved",
  "Kurgu oluşturulamadı": "Could not create the blueprint",
  "Kurgu onaylandı": "Blueprint approved",
