  "Kurgu yeniden oluşturuldu.": "Blueprint recreated.",
  "Kurgu, yazdığınız girişe göre yeniden oluşturulacak. Mevcut taslaktaki değişiklikler değişebilir. Devam edilsin mi?": "The blueprint will be recreated from your input. Changes in the current draft may be replaced. Continue?",
  "Kurgu; araştırma probleminizi, amacınızı, sorularınızı, yöntemi ve her bölümde ne yazılacağını tek ekranda gösterir. İstediğiniz yeri değiştirebilirsiniz. Onayladığınızda çalışma bu plana göre adım adım ilerler.": "The blueprint shows your research problem, aim, questions, method and what each section will cover on a single screen. Change anything you like. Once you approve it, your work proceeds step by step according to this plan.",
  "Kurguyu buna göre yeniden oluştur": "Recreate the blueprint from this",
