  "Kurguyu yapay zekâ ile oluştur": "Create the blueprint with AI",
  "Onayladıktan sonra sırasıyla başlık ve bölümler gelir.": "After approval, the title and then the sections follow.",
  "Onaylandı": "Approved",
  "Problem, amaç, sorular, yöntem ve her bölümün planı birbiriyle uyumlu olacak şekilde kuruluyor. Bu işlem 20–60 saniye sürebilir.": "Building the problem, aim, questions, method and the plan of each section so that they fit together. This may take 20–60 seconds.",
  "Problem, amaç, yöntem ve bölüm planı": "Problem, aim, method and section plan",
  "Soru ekle": "Add question",
  "Soruyu kaldır": "Remove question",
  "Taslak": "Draft",
