  "Yazmaya başlamadan önce çalışmanızı kurgulayalım": "Let’s plan your work before you start writing",
  "Yeni öneri yazıldı.": "New suggestion added.",
  "Yeniden öner": "Suggest again",
  "Yöntem tercihiniz, örnekleminiz, danışmanınızın önerileri veya kısıtlarınız varsa yazın; kurgu buna göre kurulur. Boş bırakırsanız çalışma bilgilerinizden kurgulanır.": "Write your preferred method, sample, your advisor’s suggestions or any constraints; the blueprint is built around them. If left blank, it is built from your work details.",
  "Çalışmanın kurgusu": "Study blueprint",
  "Çalışmanız bu plana göre adım adım ilerleyecek. Kurguyu istediğiniz zaman sol menüden açıp değiştirebilirsiniz.": "Your work will proceed step by step according to this plan. You can open and change the blueprint from the left menu at any time.",
  "Çalışmanızın kurgusu hazırlanıyor…": "Preparing your study blueprint…",
  "Öneri alınamadı": "Could not get a suggestion",
  "ör. Lise öğretmenleriyle görüşme yaparak nitel bir çalışma yapmak istiyorum; özellikle uzaktan eğitimde yaşadıkları zorluklara odaklanacağım.": "e.g. I want to run a qualitative study interviewing high school teachers, focusing on the difficulties they face in distance education.",
  "ör. Nicel değil nitel yöntem kullanmak istiyorum; örneklemi 15 öğretmenle sınırla.": "e.g. I want a qualitative rather than quantitative method; limit the sample to 15 teachers.",
  "Şu kısımlar boş: {list}. Yine de onaylansın mı? Daha sonra da tamamlayabilirsiniz.": "These parts are empty: {list}. Approve anyway? You can complete them later.",
