  "Hesabıma aktar": "Import to my account",
  "Hızlı kontrol": "Quick check",
  "Kabul edilen hata (ölçek biriminde)": "Acceptable error (in scale units)",
  "Kaldır": "Remove",
  "Kaynaklar yazdığınız metinden ayrıştırıldı; sonucu kontrol edin.": "Sources were parsed from your text; please check the result.",
  "Kaynakları kontrol et": "Check sources",
  "Kaynakça dili": "Reference list language",
  "Kaynakçanızı yapıştırın (her kaynak ayrı satırda). Zotero, Mendeley veya EndNote’tan alınan BibTeX/RIS da olur.": "Paste your reference list (one source per line). BibTeX/RIS from Zotero, Mendeley or EndNote also works.",
  "Kaynakçanızı yapıştırın; her kaynak ayrı satırda olsun. En fazla 30 kaynak.": "Paste your reference list, one source per line. Up to 30 sources.",
  "Kaynakçayı kopyala": "Copy reference list",
