  "Kitap adı": "Book title",
  "Kontrol ediliyor…": "Checking…",
  "Künyede fark var": "Details differ",
  "Künyeler Crossref, DataCite ve OpenAlex kayıtlarından alınır; yapay zekâ kullanılmaz.": "Details come from Crossref, DataCite and OpenAlex records; no AI is used.",
  "Madde": "Item",
  "Madde silinirse α": "α if item deleted",
  "Madde-toplam korelasyonu .30’un altında olan veya silindiğinde alfayı yükselten maddeler vurgulanmıştır; çıkarma kararını kuramsal gerekçeyle verin.": "Items with an item-total correlation below .30 or that raise alpha when deleted are highlighted; base any removal on theoretical grounds.",
  "Metin içi:": "In-text:",
  "Ortalama tahmini için %{c} güven düzeyi, σ = {sd} ve ±{e} hata payıyla gereken örneklem büyüklüğü {n} olarak hesaplanmıştır (Cochran, 1977).": "For estimating a mean with a {c}% confidence level, σ = {sd} and a ±{e} margin of error, the required sample size was calculated as {n} (Cochran, 1977).",
  "Sayfalar": "Pages",
