  "Çalışmayı birlikte yazacağınız kişileri davet edin. Ortak yazarlar bölümleri düzenler, kaynak ekler ve yapay zekâyı kendi paketleriyle kullanır; yorumcular yalnızca okur ve yorum yazar. Kim hangi bölümdeyse adı görünür; aynı bölümü aynı anda kaydederseniz hiçbir metin kaybolmaz, sürüm geçmişine saklanır.": "Invite the people you will write with. Co-authors edit sections, add sources and use AI with their own plans; commenters only read and comment. You can see who is in which section; if two people save the same section at once, nothing is lost — it is kept in the version history.",
