  "Çalışmalarınız yalnızca size ve davet ettiğiniz ortak yazarlara görünür. Satır düzeyinde güvenlik, şifreli depolama ve tek tıkla veri silme.": "Your work is visible only to you and the co-authors you invite. Row-level security, encrypted storage and one-click data deletion.",
  "Paket ölçüleri nasıl belirlendi?": "How were the plan amounts set?",
  "Aylık sayfa miktarları, 44 gerçek akademik tam metin üzerinde ölçülen ortalama sayfa uzunluğu ve bir sayfanın ortalama yapay zekâ maliyeti esas alınarak belirlenir ve paketinizin gerçek sınırıdır: yapay zekânın yazdığı taslak kelimeleri sayılır (1 sayfa = 344 kelime). Ana sayfa ve bu sayfa aynı paket kaydından beslenir.": "Monthly page amounts are based on the average page length measured on 44 real academic full texts and the average AI cost of a page, and they are your plan’s actual limit: the words of drafts written by the AI are counted (1 page = 344 words). The home page and this page are fed from the same plan record.",
  "“Sınırsız” ifadesi, bir kişinin akademik çalışması için olağan kullanımı anlatır.": "“Unlimited” means ordinary use by one person for academic work.",
