  "5. Akış şeması": "5. Flow diagram",
  "Sistematik derleme önceden tanımlanmış bir protokole göre yürür. Sorunuzu ve ölçütlerinizi yazın; tarama kararlarında gerekçe olarak bu ölçütler kullanılır ve yöntem bölümünüzde raporlanır.": "A systematic review follows a predefined protocol. Write your question and criteria; they are used as reasons in screening decisions and reported in your methods section.",
  "Araştırma sorusu (ör. PICO)": "Research question (e.g. PICO)",
  "Ör. Ortaokul öğrencilerinde oyunlaştırma, matematik başarısını geleneksel öğretime göre artırır mı?": "E.g. Does gamification improve middle-school students’ mathematics achievement compared with traditional teaching?",
  "Dahil etme ölçütleri (her satıra bir)": "Inclusion criteria (one per line)",
