  "Hariç tutma ölçütleri (her satıra bir)": "Exclusion criteria (one per line)",
  "Yanlış örneklem (yetişkinler)\nKontrol grubu yok\nTam metne ulaşılamadı": "Wrong population (adults)\nNo control group\nFull text not available",
  "Protokolü kaydet": "Save protocol",
