  "{n} kayıt": "{n} records",
  "Arama yapılamadı": "Search failed",
  "{a} kayıt eklendi, {d} yinelenen ayrıldı": "{a} records added, {d} duplicates separated",
  "Academiana’da ara": "Search in Academiana",
  "13 veri tabanında eşzamanlı arama; en fazla 50 sonuç derlemeye eklenir. Arama ifadesi yöntem bölümü için kaydedilir.": "Searches 13 databases at once; up to 50 results are added to the review. The search string is saved for the methods section.",
  "Ör. gamification AND mathematics achievement": "E.g. gamification AND mathematics achievement",
  "{n} sonuç bulundu": "{n} results found",
  "Derlemeye ekle": "Add to review",
  "Veri tabanından içe aktar": "Import from a database",
  "Scopus, Web of Science, PubMed, ERIC veya ULAKBİM’den sonuçları RIS ya da BibTeX olarak dışa aktarıp yükleyin. Yinelenenler otomatik ayrılır.": "Export results from Scopus, Web of Science, PubMed, ERIC or ULAKBİM as RIS or BibTeX and upload them. Duplicates are separated automatically.",
  "Veri tabanı adı": "Database name",
  "Kullandığınız arama ifadesi (raporlama için)": "The search string you used (for reporting)",
