  "Öneriler yalnızca yardımcıdır; her kaydın kararını siz verirsiniz. Şüpheli kayıtları tam metin aşamasına geçirmeniz önerilir.": "Suggestions are only an aid; you decide on every record. Moving doubtful records to the full-text stage is recommended.",
  "Dahil (tam metne geç)": "Include (to full text)",
  "Hariç tut": "Exclude",
  "Taranmayı bekleyen kayıt yok. Kayıt toplama sekmesinden kayıt ekleyin veya tam metin aşamasına geçin.": "No records awaiting screening. Add records in the Collect tab or move on to the full-text stage.",
  "Henüz hariç tutulan kayıt yok.": "No records excluded yet.",
  "İlk 200 kayıt gösteriliyor; karar verdikçe sıradakiler görünür.": "Showing the first 200 records; the next ones appear as you decide.",
  "Listeyi yenile": "Refresh list",
  "{n} çalışma kaynaklara eklendi": "{n} studies added to sources",
  "Kaynaklar doğrulanıyor; açık erişimli tam metinler arka planda okunur.": "Sources are being verified; open-access full texts are read in the background.",
  "Taramayı geçen çalışmaların tam metnini okuyup uygunluğa karar verin. Hariç tutulan her rapor için gerekçe akış şemasında raporlanır.": "Read the full texts of the studies that passed screening and decide on eligibility. The reason for each excluded report appears in the flow diagram.",
  "{n} dahil edilen çalışma henüz kaynaklarda değil.": "{n} included studies are not in your sources yet.",
  "Kaynaklara ekle": "Add to sources",
  "Dahil et": "Include",
