  "Ayda 25 sayfa yapay zekâ destekli akademik metin (ör. 1 makale veya tezin 2–3 bölümü)": "25 pages of AI-assisted academic text per month (e.g. 1 article or 2–3 thesis chapters)",
  "Ayda 50 sayfa yapay zekâ destekli akademik metin (ör. 2 makale; yüksek lisans tezi 1–2 ayda)": "50 pages of AI-assisted academic text per month (e.g. 2 articles; a master’s thesis in 1–2 months)",
  "Ayda 85 sayfa yapay zekâ destekli akademik metin (yüksek lisans tezi ayda bir; doktora tezi yaklaşık 2 ayda)": "85 pages of AI-assisted academic text per month (a master’s thesis a month; a doctoral thesis in about 2 months)",
  "Ayda {n} sayfa yapay zekâ destekli akademik metin": "{n} pages of AI-assisted academic text per month",
