  "Paketi yükselt": "Upgrade plan",
  "Paketleri gör": "See plans",
  // D149: içe aktarma, kaynak tercihleri, seçim menüsü
  "Çalışmanız içe aktarıldı": "Your work has been imported",
  "{s} bölüm · {r} kaynak · {l} atıf bağlandı": "{s} sections · {r} sources · {l} citations linked",
  "Mevcut çalışmamı içe aktar": "Import my existing work",
  "Dosya yükleniyor…": "Uploading file…",
  "Yapay zekâ çalışmanızı analiz ediyor; bölümler, kaynaklar ve atıflar hazırlanıyor… Büyük belgelerde bir dakika sürebilir.": "The AI is analysing your work; sections, sources and citations are being prepared… Large documents may take a minute.",
  "Word (.docx), PDF veya metin dosyası. Yapay zekâ türünü ve konusunu çıkarır, bölümlere ayırır, kaynakçayı ekler, atıfları bağlar ve çalışma ekranını açar. Metniniz yeniden yazılmaz.": "Word (.docx), PDF or text file. The AI identifies its type and topic, splits it into sections, adds the reference list, links the citations and opens the workspace. Your text is not rewritten.",
  "veya yeni bir çalışma başlatın": "or start a new work",
  "Güçlü konu tanımı": "Strong topic description",
  "Orta konu tanımı": "Moderate topic description",
  "Zayıf konu tanımı": "Weak topic description",
  "Yapay zekâ bölümleri bu bağlamla daha isabetli yazar.": "With this context the AI writes the sections more accurately.",
  "Daha isabetli üretim için şunları ekleyin: {x}": "For more accurate output, add: {x}",
  "Atıf ve kaynak tercihlerinizi ayarlayalım": "Let’s set your citation and source preferences",
  "Bu tercihleri sonradan Proje ayarları’ndan değiştirebilirsiniz. Kendi kaynaklarınızı (PDF, Zotero, Mendeley, .bib/.ris) çalışma ekranındaki “İçe aktar” düğmesiyle istediğiniz an ekleyebilirsiniz.": "You can change these preferences later in Project settings. You can add your own sources (PDF, Zotero, Mendeley, .bib/.ris) at any time with the “Import” button in the workspace.",
  "Çalışmanızı nasıl yapılandırmak istersiniz?": "How would you like to structure your work?",
  "Standart bölümler": "Standard sections",
  "Seçtiğiniz türün akademik bölüm düzeni (ör. Giriş, Yöntem, Bulgular, Tartışma).": "The academic section layout of the chosen type (e.g. Introduction, Method, Results, Discussion).",
  "Akıllı bölüm planı": "Smart section plan",
  "Yapay zekâ konunuza göre problem, amaç, yöntem ve bölüm planını hedef uzunluklarıyla önerir; onayladığınız plana göre yazılır.": "The AI proposes the problem, aim, method and a section plan with target lengths for your topic; writing follows the plan you approve.",
  "Serbest": "Free form",
  "Tek bir metin bölümüyle başlayın; alt başlıkları kendiniz ekleyin.": "Start with a single text section and add subheadings yourself.",
  "Veri tabanı taraması": "Database search",
  "Yazarken gerektiğinde OpenAlex, Crossref, DergiPark gibi akademik veri tabanlarında gerçek kaynak aranır.": "While writing, real sources are searched in academic databases such as OpenAlex, Crossref and DergiPark when needed.",
  "Her seferinde sor": "Ask every time",
