  "DOI / PMID / arXiv ile ekle": "Add by DOI / PMID / arXiv",
  "Kimliği yapıştırın; künye kayıt otoritesinden gelir.": "Paste the identifier; the reference comes from the registration agency.",
  ".bib / .ris içe aktar": "Import .bib / .ris",
  "EndNote, JabRef ve diğer programların dosyaları.": "Files from EndNote, JabRef and other programs.",
  "Yazdığınız çalışmayı yükleyin. Metniniz yeniden yazılmaz: en üst düzey başlıklarınız bölüm olur, boş bölümlere yerleşir; dolu bölümlerin üzerine yazılmaz. Kaynakça doğrulanıp eklenir, metin içi atıflar bağlanır.": "Upload the work you have written. Your text is not rewritten: your top-level headings become sections and fill empty sections; sections with text are never overwritten. The reference list is verified and added, and in-text citations are linked.",
  "En iyi sonuç Word (.docx) ile alınır; PDF’te başlıklar ve paragraflar yaklaşık olarak çıkarılır.": "Word (.docx) gives the best result; in PDFs, headings and paragraphs are detected approximately.",
  "Dosya seç": "Choose file",
  "Bilgisayarınızdan en fazla 10 makale PDF’i seçin. Künye DOI ile doğrulanır, tam metin okunur ve “Kaynağa sor” ile kullanılabilir.": "Choose up to 10 article PDFs from your computer. The reference is verified via DOI, the full text is read and can be used with “Ask the source”.",
  "PDF seç": "Choose PDFs",
  "zotero.org → Settings → Security (Feeds/API) sayfasını açın.": "Open zotero.org → Settings → Security (Feeds/API).",
  "“Your user ID for use in API calls” numarasını kopyalayın.": "Copy the number shown as “Your user ID for use in API calls”.",
  "“Create new private key” ile yalnızca okuma izinli bir anahtar oluşturun.": "Create a read-only key with “Create new private key”.",
