  "Anahtarınız saklanmaz; yalnızca bu aktarım için kullanılır. En fazla 300 kayıt aktarılır, ekler ve notlar alınmaz.": "Your key is not stored; it is used only for this import. Up to 300 records are imported; attachments and notes are not.",
  "Zotero’dan aktar": "Import from Zotero",
  "Mendeley Reference Manager’da aktarmak istediğiniz kaynakları seçin (tümü için Ctrl/Cmd+A).": "In Mendeley Reference Manager, select the references you want to import (Ctrl/Cmd+A for all).",
  "Sağ tık → “Export” (Dışa aktar) → BibTeX (.bib) veya RIS (.ris) seçip kaydedin.": "Right-click → “Export” → choose BibTeX (.bib) or RIS (.ris) and save.",
  "Kaydettiğiniz dosyayı aşağıdan yükleyin.": "Upload the saved file below.",
  "Mendeley, üçüncü taraf uygulamalara doğrudan bağlantıyı kısıtladığı için aktarım dosya ile yapılır.": "Because Mendeley restricts direct connections from third-party apps, the import works via a file.",
  "BibTeX (.bib), RIS (.ris) veya CSL-JSON (.json) dosyası yükleyin. Kaynaklar DOI ile doğrulanır; projede olanlar atlanır.": "Upload a BibTeX (.bib), RIS (.ris) or CSL-JSON (.json) file. Sources are verified via DOI; those already in the project are skipped.",
