  "Bitirme projesinin türü": "Type of capstone project",
  "Uygulama projelerine sırf akademik görünmesi için hipotez, örneklem veya istatistik başlıkları eklenmez.": "Applied projects do not get hypothesis, sample or statistics headings just to look academic.",
  "Yaklaşım; bölümleri, yöntem ve bulgu başlıklarını ve kalite ölçütlerini değiştirir (ör. nitel çalışmada “Çalışma grubu” ve “İnandırıcılık”, karma yöntemde “Entegrasyon”).": "The approach changes the sections, the method and findings headings and the quality criteria (e.g. “Participants” and “Trustworthiness” in a qualitative study, “Integration” in mixed methods).",
  "Araştırma deseni (isteğe bağlı)": "Research design (optional)",
  "Henüz belirlemedim": "Not decided yet",
  "Desen, yöntem ve bulgular bölümündeki alt başlıkları ve raporlama standardını belirler.": "The design determines the subheadings in the method and findings sections and the reporting standard.",
  "Yönteminizi henüz bilmiyor musunuz?": "Not sure about your method yet?",
  "Konunuzu, amacınızı ve elinizdeki veri olanaklarını birkaç cümleyle yazın; gerekçeli bir yaklaşım ve desen önerisi alın. Nihai karar sizin ve danışmanınızındır.": "Describe your topic, aim and the data you can access in a few sentences to get a reasoned approach and design suggestion. The final decision is yours and your supervisor’s.",
  "ör. Öğretmenlerin uzaktan eğitim deneyimlerini ve bu deneyimin mesleki tükenmişlikle ilişkisini anlamak istiyorum; okullara erişimim var.": "e.g. I want to understand teachers’ experiences of remote teaching and how they relate to occupational burnout; I have access to schools.",
  "Yöntem önerisi al": "Get a method suggestion",
  "Önerilen yaklaşım:": "Suggested approach:",
  "Gerekçe:": "Rationale:",
  "Sınırlılıklar:": "Limitations:",
  "Alternatifler:": "Alternatives:",
  "Kayıtlı şablonum": "My saved template",
  "Daha önce kaydettiğiniz bölüm yapısıyla başlayın (başlıklar, sıra, zorunluluk ve kapsam; metin kopyalanmaz).": "Start with a section structure you saved earlier (headings, order, requirement and scope; no text is copied).",
  "Şablon kullanma": "Don’t use a template",
  "Kayıtlı şablonunuzun bölüm yapısı kullanılacak.": "The section structure of your saved template will be used.",
  "Akademik tutarlılık zinciri": "Academic consistency chain",
  "Problem, soru, yöntem, örneklem, analiz, bulgu ve tartışma arasındaki bağlantılar. Bu öneriler puanı etkilemez ve otomatik düzeltme yapılmaz; kabul edip etmemek size kalmıştır.": "Links between problem, questions, method, sample, analysis, findings and discussion. These suggestions do not affect the score and nothing is changed automatically; it is up to you whether to accept them.",
  "Kanıt:": "Evidence:",
  "Puan 100’den başlar; kural tabanlı her bulgu önemine göre puan düşürür: Kritik {e}, Önemli {w}, İyileştirme {i} puan. Bazı küçük bulgular (ör. çift boşluk) daha düşük ağırlıkla sayılır. Puan 0–100 arasında sınırlanır.": "The score starts at 100; each rule-based finding deducts points by importance: Critical {e}, Important {w}, Improvement {i} points. Some minor findings (e.g. double spaces) count with a lower weight. The score is limited to 0–100.",
  "Bölüm ayarları kaydedildi": "Section settings saved",
  "{title} (kopya)": "{title} (copy)",
  "Bölüm kopyalandı": "Section duplicated",
  "Alt başlıklar kopyalandı; metin kopyalanmaz.": "Subheadings were copied; text is not copied.",
  "Bölüm ayarları": "Section settings",
  "Varsayılana döndür": "Restore default",
  "Bu bölüm neden var?": "Why is this section here?",
  "Bu çalışma türü için kritik bölüm.": "A critical section for this type of work.",
  "Bölüm adı": "Section name",
