  "Kapsam": "Scope",
  "Yapay zekâ bu bölümü yazarken uzunluğu buna göre ayarlar.": "The AI adjusts the length accordingly when writing this section.",
  "Bu bölümü gizle": "Hide this section",
  "Gizli bölüm silinmez; dışa aktarılan belgeye, otomatik yazıma ve yapay zekâ bağlamına girmez. İstediğiniz zaman yeniden açabilirsiniz.": "A hidden section is not deleted; it is left out of exported documents, automatic writing and the AI context. You can show it again at any time.",
  "Yapı yüklenemedi": "Could not load the structure",
  "Seçilen değişiklikler uygulandı": "Selected changes applied",
  "Metni olduğu için kaldırılmayan bölümler: {list}": "Sections not removed because they contain text: {list}",
  "Uygulanamadı": "Could not apply",
  "Şablon kaydedildi": "Template saved",
  "Yeni proje oluştururken “Kayıtlı şablonum” bölümünden seçebilirsiniz.": "You can select it under “My saved template” when creating a new project.",
  "Şablon kaydedilemedi": "Could not save the template",
  "“{name}” şablonu silinsin mi? Bu şablonla oluşturulmuş projeler etkilenmez.": "Delete the template “{name}”? Projects created with it are not affected.",
  "Yapıyı yönet": "Manage structure",
  "Bölüm yapınızı Academiana’nın güncel şablonuyla veya kaydettiğiniz bir şablonla karşılaştırın. Hiçbir değişiklik siz seçip onaylamadan uygulanmaz; metni olan bölümler silinmez.": "Compare your section structure with Academiana’s current template or with a template you saved. No change is applied until you select and confirm it; sections that contain text are never deleted.",
  "Karşılaştırılacak yapı": "Structure to compare with",
  "Academiana varsayılan şablonu": "Academiana default template",
  "Varsayılana sıfırla (tümünü seç)": "Reset to default (select all)",
  "Academiana şablonu güncellendi (sürüm {a} → {b}). Projeniz kendiliğinden değişmez; aşağıdaki farkları inceleyip istediklerinizi uygulayabilirsiniz.": "The Academiana template has been updated (version {a} → {b}). Your project does not change by itself; review the differences below and apply the ones you want.",
  "Yapınız seçilen şablonla uyumlu; uygulanacak fark yok.": "Your structure matches the selected template; there are no differences to apply.",
  "Eklenebilecek bölümler": "Sections that can be added",
  "Adı farklı olan bölümler": "Sections with a different name",
  "Şablonda olmayan bölümler": "Sections not in the template",
  "Metni olduğu için kaldırılmaz; isterseniz bölüm ayarlarından gizleyebilirsiniz.": "Not removed because it contains text; you can hide it in the section settings if you like.",
  "Seçilenleri uygula ({n})": "Apply selected ({n})",
  "Bu yapıyı şablon olarak kaydet": "Save this structure as a template",
  "Başlıklar, sıra, açıklamalar, zorunluluk ve kapsam kaydedilir; metin kaydedilmez.": "Headings, order, descriptions, requirement and scope are saved; text is not saved.",
  "Şablon kaydı için veritabanı güncellemesi henüz yapılmamış.": "The database update needed for saving templates has not been run yet.",
  "ör. Nitel yüksek lisans tezi yapım": "e.g. My qualitative master’s thesis structure",
  "Şablonu sil": "Delete template",
