  "“{title}” bu çalışma türü için kritik bir bölümdür.": "“{title}” is a critical section for this type of work.",
  "Silerseniz çalışmanın akademik bütünlüğü zarar görebilir ve kalite kontrolünde eksik olarak görünebilir.": "Deleting it may harm the academic integrity of the work, and it may appear as missing in the quality check.",
  "Silmek yerine bölüm ayarlarından gizleyebilirsiniz.": "Instead of deleting it, you can hide it in the section settings.",
  "Gizli bölüm": "Hidden section",
  "Bölüm eklendi": "Section added",
  "Bölüm silindi": "Section deleted",
  "Bölüm ayarları değişti": "Section settings changed",
  "Bölüm sırası değişti": "Section order changed",
