  "güncel sürümünü resmi kaynağından kontrol edin": "check the current version at its official source",
  "İşlevler başlık olarak birebir kopyalanmaz; yapay zekâ alt başlıkları konunuza göre adlandırır.": "Functions are not copied verbatim as headings; the AI names subheadings according to your topic.",
  "Bu değişiklik geri alınsın mı? Metin içeren bölümler silinmez.": "Undo this change? Sections that contain text are not deleted.",
  "Değişiklik geri alındı": "Change undone",
  "Geri alınamadı": "Could not undo",
  "geri alındı": "undone",
  "Araştırma soruları veya amaç değişti": "Research questions or aim changed",
  "Yöntem, analiz planı, bulgular ve tartışmanın yeni sorularla uyumunu kalite kontrolündeki “Akademik tutarlılık zinciri”nden kontrol edin.": "Check in the quality check’s “Academic consistency chain” whether the method, analysis plan, findings and discussion still fit the new questions.",
  "Kaynaklar sentezlenmek yerine ardışık özetlenmiş olabilir": "Sources may be summarised one after another instead of synthesised",
  "“{s}” bölümündeki atıflı paragrafların %{p}’i yalnızca tek bir kaynağa dayanıyor.": "{p}% of the cited paragraphs in “{s}” rely on a single source only.",
  "Paragrafları kaynak kaynak değil tema tema kurun; aynı paragrafta birden çok çalışmayı karşılaştırın.": "Build paragraphs by theme rather than source by source; compare several studies within the same paragraph.",
  "Çelişkili bulgular ele alınmamış görünüyor": "Conflicting findings do not seem to be addressed",
  "“{s}” bölümünde çalışmalar arasındaki farklılık veya çelişkiye işaret eden bir ifade bulunamadı.": "No wording pointing to differences or contradictions between studies was found in “{s}”.",
  "Uzlaşan ve çelişen bulguları, yöntem farklılıklarını ve olası nedenlerini karşılaştırın.": "Compare consistent and conflicting findings, methodological differences and their possible causes.",
  "Güncel çalışmalar temsil edilmiyor": "Recent studies are not represented",
  "“{s}” bölümünde atıf yapılan kaynakların hiçbiri son 5 yıla ait değil (en yenisi {y}).": "None of the sources cited in “{s}” is from the last 5 years (the most recent is from {y}).",
  "Temel çalışmaların yanında alanın güncel ampirik çalışmalarını da ekleyin (Literatür araştır).": "Alongside foundational works, add recent empirical studies from the field (Search literature).",
  "Yinelenen başlık": "Duplicate heading",
  "“{h}” başlığı birden fazla yerde geçiyor.": "The heading “{h}” appears in more than one place.",
  "Aynı işlevi gören başlıkları birleştirin veya içeriğe özgü, ayırt edici adlar verin.": "Merge headings that serve the same function or give them distinctive, content-specific names.",
  "Ön sayfalar (onay, beyan, önsöz)": "Front matter (approval, declaration, preface)",
  "Enstitünün istediği ön sayfaları (onay sayfası, bilimsel etik beyanı, önsöz/teşekkür, kısaltmalar) hazırlamak; kapak, içindekiler ve tablo/şekil listeleri dışa aktarmada otomatik oluşur.": "To prepare the front matter required by the institute (approval page, declaration of academic ethics, preface/acknowledgements, abbreviations); the cover, table of contents and lists of tables/figures are generated automatically on export.",
  "Enstitü kılavuzundaki onay ve beyan sayfası metnini kılavuzdan aynen alın.": "Take the approval and declaration page text exactly as given in the institute’s guidelines.",
  "Jüri üyeleri, tarih ve imza alanlarını kendi bilgilerinizle doldurun.": "Fill in the committee members, date and signature fields with your own information.",
  "İsterseniz önsöz/teşekkür ve kısaltmalar listesini ekleyin.": "Add a preface/acknowledgements and a list of abbreviations if you wish.",
  "Jüri adı, tarih, onay veya etik kurul bilgisi uydurulmaz; bilinmeyen alanlar [VERİ GİRİLECEK] olarak bırakılır.": "Committee names, dates, approvals or ethics board details are never invented; unknown fields are left as [DATA TO BE ENTERED].",
  "Beyan metni enstitünün resmi metnidir; kılavuzda varsa aynen kullanılır.": "The declaration is the institute’s official text; if it is in the guidelines, it is used verbatim.",
  "Enstitünüzün onay ve beyan sayfası şablonu var mı?": "Does your institute have a template for the approval and declaration pages?",
  "Onay sayfası, bilimsel etik beyanı ve önsöz enstitü kılavuzuna göre eklenir; kapak, içindekiler ve tablo/şekil listeleri dışa aktarmada otomatik oluşur.": "The approval page, declaration of academic ethics and preface are added according to the institute’s guidelines; the cover, table of contents and lists of tables/figures are generated automatically on export.",
  "Tezlerde Türkçe özet ve İngilizce abstract ön sayfalarda yer alır; tüm bölümler yazıldıktan sonra en son yazılır.": "In theses, the Turkish abstract (özet) and English abstract appear in the front matter; they are written last, after all chapters.",
  "Çağrının istediği ekler (özgeçmiş, kurum izinleri, ölçekler) varsa eklenir.": "Annexes required by the call (CVs, institutional permissions, scales) are added if applicable.",
